// Parses the comma-separated "Key: Value" Test Data column into a
// structured object matching what the Playwright server expects.
// N/A rows (e.g. TC001, TC014-TC017, TC020's precondition-only cases)
// produce an empty object, which the server's runners treat as "no
// username/password supplied" and handle gracefully (BLOCKED, not a crash).
//
// IMPORTANT: this node now receives a BATCH of items at once (batchSize 5
// on the loop upstream), not one at a time - it must iterate over every
// item and return one output per input, or items silently get dropped.

const items = $input.all();

return items.map((item) => {
  const raw = item.json["Test Data"] || "";
  const testData = {};

  if (raw && raw.trim().toUpperCase() !== "N/A") {
    raw.split(",").forEach((pair) => {
      const colonIndex = pair.indexOf(":");
      if (colonIndex === -1) return;
      const key = pair.slice(0, colonIndex).trim();
      let value = pair.slice(colonIndex + 1);
      if (value.startsWith(" ")) value = value.slice(1);
      testData[key] = value;
    });
  }

  return {
    json: {
      ...item.json,
      parsedTestData: testData,
      requestStartedAt: Date.now()
    }
  };
});

