// Wraps each synchronous result from the Playwright server into the
// shape v4.0B's webhook expects: { results: [ {...} ] }.
//
// IMPORTANT: this node now receives a BATCH of items at once (batchSize 5
// upstream), not one at a time. Uses itemMatching(index) to correctly
// pair each Playwright result with ITS OWN original sheet row and start
// time - using .item (singular) here would silently reuse item 0's data
// for every result in the batch.

const results = $input.all();

return results.map((item, index) => {
  const original = $('Filter Ready Test Cases').itemMatching(index).json;
  const execResult = item.json;
  const startedAt = $('Parse Test Data').itemMatching(index).json.requestStartedAt;
  const finishedAt = Date.now();
  const durationLabel = startedAt ? ((finishedAt - startedAt) / 1000).toFixed(1) + "s" : "";

  return {
    json: {
      results: [
        {
          "Test Case ID": execResult.testCaseId,
          "Story ID": original["Story ID"],
          "Unique Test Case Key": original["Unique Test Case Key"],
          "Version": original["Version"],
          "Expected Result": original["Expected Result"],
          "Actual Result": execResult.actualResult,
          "Execution Date": new Date().toISOString(),
          "Executed By": "QualityGrid Automation (n8n)",
          "Browser": "Chromium",
          "Environment": "quality-fashion.lovable.app",
          "Screenshot/Evidence": execResult.screenshotPath || "",
          "Execution Duration": durationLabel
        }
      ]
    }
  };
});
